theorem p0507 {d : (Fin 20) → (Fin 20) → ℕ}
  (hd : ∀ a b, d a b = sInf {n | ∃ p : List (Fin 20), p.length = n ∧ p[0]! = a ∧ p.getLast! = b}) :
  let s := {x : Fin 20 × Fin 20 | x.1 ≠ x.2 ∧ d x.1 x.2 > d x.2 x.1}
  let t := {x : Fin 20 × Fin 20 | x.1 ≠ x.2}
  let m := s.ncard
  let n := t.ncard
  m + n = <candidate> := by sorry

